  "infoKk": "Хангыль 1443 жылы Седжон хан қолдауымен құрылған. Алғашқы атауы — «Хунмин чонъым» (халыққа дұрыс айту жөніндегі нұсқау). Корейде 9 қазан — Хангыль күні. Әріптер 3 белгіден тұрады: нүкте (Аспан), көлденең сызык ㅡ (Жер), тік сызық ㅣ (Адам).",
