     "ruleKk": "Қағида: тамыр дауысты дыбыс немесе ㄹ-мен аяқталса -ㄹ까요?, дауыссызбен аяқталса -(으)ㄹ까요? жалғанатын. Мысалы: 먹 + 을까요 → 먹을까요?",
