      "ko": "나기마 씨, 오늘 마지나 씨 생일 선물을 사러 백화점에 갈 수 있어요?",
      "kk": "Нагима, бүгін Мадинаға туған күн сыйлығын сатып алуға сауда үйіне бара аламыз ба?",
      "ru": "Нагима, можем ли мы сегодня пойти в универмаг, чтобы купить подарок Мадине на день рождения?",
